484:   private async flushPendingFormSubmissions(userId: string, deviceId: string): Promise<void> {
485:     if (this.cache.pendingFormSubmissions.length === 0) {
486:       return;
487:     }
488: 
489:     console.log(`CanvasSync: Syncing ${this.cache.pendingFormSubmissions.length} form submissions`);
490: 
491:     // Only explicit pending rows may dispatch. Legacy rows without a delivery
492:     // status, interrupted dispatches, and uncertain writes are left untouched.
493:     const submissions = [...this.cache.pendingFormSubmissions];
494: 
495:     for (const submission of submissions) {
496:       if (submission.deliveryStatus !== 'pending') {
497:         continue;
498:       }
499: 
500:       // Persist the dispatch boundary before any transport attempt.
501:       submission.deliveryStatus = 'dispatching';
502:       try {
503:         await this.saveCache();
504:       } catch (error) {
505:         // No POST occurred, so this in-memory row is still known undispatched.
506:         submission.deliveryStatus = 'pending';
507:         throw error;
508:       }
509: 
510:       let accepted = false;
511:       try {
512:         const response = await apiService.post(`/api/canvas/${submission.canvasId}/submit`, {
513:           form_data: submission.formData,
514:           submitted_at: submission.submittedAt,
515:         });
516:         accepted = response.success;
517:       } catch (error) {
518:         console.error(`CanvasSync: Failed to sync form submission for canvas ${submission.canvasId}:`, error);
519:       }
520: 
521:       if (!accepted) {
522:         // The POST may have reached the server. Keep the exact queued input and
523:         // identifiers, but never automatically repeat an uncertain dispatch.
524:         submission.deliveryStatus = 'effect_unknown';
525:         await this.saveCache();
526:         continue;
527:       }
528: 
529:       // Transport acceptance is not business completion. Remove only the exact
530:       // object that was dispatched; concurrent additions are preserved.
531:       const index = this.cache.pendingFormSubmissions.indexOf(submission);
532:       if (index < 0) {
533:         continue;
534:       }
535:       this.cache.pendingFormSubmissions.splice(index, 1);
536: 
537:       try {
538:         await this.saveCache();
539:       } catch (error) {
540:         // The durable row still says dispatching. Keep the uncertainty visible
541:         // in memory so this process cannot dispatch it again either.
542:         submission.deliveryStatus = 'effect_unknown';
543:         if (this.cache.pendingFormSubmissions.indexOf(submission) === -1) {
544:           const restoreIndex = Math.min(index, this.cache.pendingFormSubmissions.length);
545:           this.cache.pendingFormSubmissions.splice(restoreIndex, 0, submission);
546:         }
547:         throw error;
548:       }
549: 
550:       console.log(`CanvasSync: Synced form submission for canvas ${submission.canvasId}`);
551:     }
552:   }
